window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-83517aaaf6e5b2fc"]={"versions": [{"id": "FIG-83517aaaf6e5b2fc", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm für synchrone BSW-API-Kaskade).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Aktivierung des Hardware-Sendezeitstempel-Mechanismus (Egress Timestamping) für einen dedizierten Ethernet-Sendepuffer gemäß IEEE 802.1AS (gPTP).\n</li><li><strong>Architektur-Einordnung:</strong> BSW-Kommunikationsstack der AUTOSAR Classic Platform. Das Modul <code>EthTSyn</code> (Time Synchronization over Ethernet) agiert als Client des <code>EthIf</code> (Ethernet Interface), welches die Anforderung an den MCAL-Treiber <code>Eth</code> (Ethernet Driver) durchreicht.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte BSW-Module (Lebenslinien):</strong>\n<ul class=\"fig-list\"><li><code>EthTSyn</code>: Obere Transportschicht für Zeitsynchronisation; initiiert die Zeitstempelerfassung für Sync-/Pdelay-Frames.\n</li><li><code>EthIf</code>: Hardware-Abstraktionsschicht; entkoppelt Controller-Indizes und leitet Puffer-Operationen an den zuständigen Treiber weiter.\n</li><li><code>Eth</code>: MCAL-Treiber; parametrisiert die MAC-/PHY-Hardware-Register bzw. TX-Deskriptoren.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>EthIf_EnableEgressTimeStamp(CtrlIdx: uint8, BufIdx: Eth_BufIdxType): Std_ReturnType</code>\n</li><li><code>Eth_EnableEgressTimestamp(CtrlIdx: uint8, BufIdx: Eth_BufIdxType): Std_ReturnType</code>\n</li></ul>\n</li><li><strong>Parameter &amp; Typen:</strong>\n<ul class=\"fig-list\"><li><code>CtrlIdx</code> (<code>uint8</code>): Index des Ethernet-Controllers im virtuellen (<code>EthIf</code>) bzw. physischen (<code>Eth</code>) Scope.\n</li><li><code>BufIdx</code> (<code>Eth_BufIdxType</code>): Eindeutiger Bezeichner des reservierten TX-Puffers.\n</li><li>Rückgabewert: <code>Std_ReturnType</code> (<code>E_OK</code> / <code>E_NOT_OK</code>).\n</li></ul>\n</li><li><strong>Guard Condition:</strong>\n<ul class=\"fig-list\"><li><code>[EthTSynHardwareTimestampSupport == TRUE]</code>: Pre-Compile- bzw. Link-Time-Schalter; kapselt den Aufruf gegen rein softwarebasierte Zeitstempel-Implementierungen ab.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> <code>EthTSyn</code> bereitet das Senden einer zeitsynchronisationskritischen PDU vor, nachdem zuvor über <code>EthIf_ProvideTxBuffer()</code> ein Sendepuffer allokiert wurde.\n</li><li><strong>Bedingungsprüfung:</strong> Lokale Evaluation des Konfigurationsparameters <code>EthTSynHardwareTimestampSupport</code>. Ist dieser <code>FALSE</code>, wird die Sequenz übersprungen (Software-Timestamping oder inkompatible Hardware).\n</li><li><strong>Synchrone Weiterleitung:</strong>\n<ul class=\"fig-list\"><li><code>EthTSyn</code> ruft blockierend <code>EthIf_EnableEgressTimeStamp()</code> auf.\n</li><li><code>EthIf</code> mappt den <code>CtrlIdx</code> auf den physischen Controller und ruft synchron <code>Eth_EnableEgressTimestamp()</code> auf.\n</li></ul>\n</li><li><strong>Hardware-Parametrierung &amp; Rückmeldung:</strong>\n<ul class=\"fig-list\"><li>Der <code>Eth</code>-Treiber markiert den Puffer <code>BufIdx</code> (z. B. Setzen des IEEE 1588 / Egress-Capture-Flags im TX-Deskriptor).\n</li><li>Synchrone Rückgabe von <code>E_OK</code> (bzw. <code>E_NOT_OK</code> bei ungültigem Puffer/Controller) kaskadierend über <code>EthIf</code> zurück an <code>EthTSyn</code>.\n</li></ul>\n</li><li><strong>Folgeschritt:</strong> Nach erfolgreicher Rückgabe stößt <code>EthTSyn</code> den eigentlichen Sendevorgang via <code>EthIf_Transmit()</code> an.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Timing &amp; Aufruf-Reihenfolge:</strong> Der Aufruf muss zwingend <strong>vor</strong> <code>EthIf_Transmit()</code> und <strong>nach</strong> erfolgreichem <code>EthIf_ProvideTxBuffer()</code> erfolgen. Eine Aktivierung nach Übergabe an die Hardware-Sendewarteschlange führt zum Verlust des Hardware-Zeitstempels.\n</li><li><strong>Konfigurationsabhängigkeit:</strong> \n<ul class=\"fig-list\"><li>Erfordert gesetztes <code>EthTSynHardwareTimestampSupport = TRUE</code>.\n</li><li>Sowohl <code>EthIf</code> als auch <code>Eth</code> müssen das Feature unterstützen (<code>EthEnableEgressTimeStamp == TRUE</code> bzw. äquivalente MCAL-Konfiguration).\n</li></ul>\n</li><li><strong>MCAL-Treiberanforderungen:</strong> Der Ethernet-Treiber muss sicherstellen, dass nach dem Senden der Frame-spezifische Egress-Timestamp erfasst und für den anschließenden Abruf via <code>Eth_GetEgressTimeStamp()</code> / <code>EthIf_GetEgressTimeStamp()</code> im Speicher vorgehalten wird.\n</li><li><strong>API-Signatur-Diskrepanz (Naming):</strong> In der AUTOSAR-SWS weicht die Binnen-Großschreibung zwischen den Layern minimal ab (<code>EthIf_EnableEgressTimeStamp</code> mit großem <code>S</code> vs. <code>Eth_EnableEgressTimestamp</code> mit kleinem <code>s</code>). Dies ist bei statischen Bindungen und Mocking zwingend zu beachten.\n</li></ul>"}, {"id": "FIG-605bad33f004ce66", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm für synchrone BSW-API-Kaskade).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Aktivierung des Hardware-Sendezeitstempel-Mechanismus (Egress Timestamping) für einen dedizierten Ethernet-Sendepuffer gemäß IEEE 802.1AS (gPTP).\n</li><li><strong>Architektur-Einordnung:</strong> BSW-Kommunikationsstack der AUTOSAR Classic Platform. Das Modul <code>EthTSyn</code> (Time Synchronization over Ethernet) agiert als Client des <code>EthIf</code> (Ethernet Interface), welches die Anforderung an den MCAL-Treiber <code>Eth</code> (Ethernet Driver) durchreicht.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte BSW-Module (Lebenslinien):</strong>\n<ul class=\"fig-list\"><li><code>EthTSyn</code>: Obere Transportschicht für Zeitsynchronisation; initiiert die Zeitstempelerfassung für Sync-/Pdelay-Frames.\n</li><li><code>EthIf</code>: Hardware-Abstraktionsschicht; entkoppelt Controller-Indizes und leitet Puffer-Operationen an den zuständigen Treiber weiter.\n</li><li><code>Eth</code>: MCAL-Treiber; parametrisiert die MAC-/PHY-Hardware-Register bzw. TX-Deskriptoren.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>EthIf_EnableEgressTimeStamp(CtrlIdx: uint8, BufIdx: Eth_BufIdxType): Std_ReturnType</code>\n</li><li><code>Eth_EnableEgressTimestamp(CtrlIdx: uint8, BufIdx: Eth_BufIdxType): Std_ReturnType</code>\n</li></ul>\n</li><li><strong>Parameter &amp; Typen:</strong>\n<ul class=\"fig-list\"><li><code>CtrlIdx</code> (<code>uint8</code>): Index des Ethernet-Controllers im virtuellen (<code>EthIf</code>) bzw. physischen (<code>Eth</code>) Scope.\n</li><li><code>BufIdx</code> (<code>Eth_BufIdxType</code>): Eindeutiger Bezeichner des reservierten TX-Puffers.\n</li><li>Rückgabewert: <code>Std_ReturnType</code> (<code>E_OK</code> / <code>E_NOT_OK</code>).\n</li></ul>\n</li><li><strong>Guard Condition:</strong>\n<ul class=\"fig-list\"><li><code>[EthTSynHardwareTimestampSupport == TRUE]</code>: Pre-Compile- bzw. Link-Time-Schalter; kapselt den Aufruf gegen rein softwarebasierte Zeitstempel-Implementierungen ab.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> <code>EthTSyn</code> bereitet das Senden einer zeitsynchronisationskritischen PDU vor, nachdem zuvor über <code>EthIf_ProvideTxBuffer()</code> ein Sendepuffer allokiert wurde.\n</li><li><strong>Bedingungsprüfung:</strong> Lokale Evaluation des Konfigurationsparameters <code>EthTSynHardwareTimestampSupport</code>. Ist dieser <code>FALSE</code>, wird die Sequenz übersprungen (Software-Timestamping oder inkompatible Hardware).\n</li><li><strong>Synchrone Weiterleitung:</strong>\n<ul class=\"fig-list\"><li><code>EthTSyn</code> ruft blockierend <code>EthIf_EnableEgressTimeStamp()</code> auf.\n</li><li><code>EthIf</code> mappt den <code>CtrlIdx</code> auf den physischen Controller und ruft synchron <code>Eth_EnableEgressTimestamp()</code> auf.\n</li></ul>\n</li><li><strong>Hardware-Parametrierung &amp; Rückmeldung:</strong>\n<ul class=\"fig-list\"><li>Der <code>Eth</code>-Treiber markiert den Puffer <code>BufIdx</code> (z. B. Setzen des IEEE 1588 / Egress-Capture-Flags im TX-Deskriptor).\n</li><li>Synchrone Rückgabe von <code>E_OK</code> (bzw. <code>E_NOT_OK</code> bei ungültigem Puffer/Controller) kaskadierend über <code>EthIf</code> zurück an <code>EthTSyn</code>.\n</li></ul>\n</li><li><strong>Folgeschritt:</strong> Nach erfolgreicher Rückgabe stößt <code>EthTSyn</code> den eigentlichen Sendevorgang via <code>EthIf_Transmit()</code> an.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Timing &amp; Aufruf-Reihenfolge:</strong> Der Aufruf muss zwingend <strong>vor</strong> <code>EthIf_Transmit()</code> und <strong>nach</strong> erfolgreichem <code>EthIf_ProvideTxBuffer()</code> erfolgen. Eine Aktivierung nach Übergabe an die Hardware-Sendewarteschlange führt zum Verlust des Hardware-Zeitstempels.\n</li><li><strong>Konfigurationsabhängigkeit:</strong> \n<ul class=\"fig-list\"><li>Erfordert gesetztes <code>EthTSynHardwareTimestampSupport = TRUE</code>.\n</li><li>Sowohl <code>EthIf</code> als auch <code>Eth</code> müssen das Feature unterstützen (<code>EthEnableEgressTimeStamp == TRUE</code> bzw. äquivalente MCAL-Konfiguration).\n</li></ul>\n</li><li><strong>MCAL-Treiberanforderungen:</strong> Der Ethernet-Treiber muss sicherstellen, dass nach dem Senden der Frame-spezifische Egress-Timestamp erfasst und für den anschließenden Abruf via <code>Eth_GetEgressTimeStamp()</code> / <code>EthIf_GetEgressTimeStamp()</code> im Speicher vorgehalten wird.\n</li><li><strong>API-Signatur-Diskrepanz (Naming):</strong> In der AUTOSAR-SWS weicht die Binnen-Großschreibung zwischen den Layern minimal ab (<code>EthIf_EnableEgressTimeStamp</code> mit großem <code>S</code> vs. <code>Eth_EnableEgressTimestamp</code> mit kleinem <code>s</code>). Dies ist bei statischen Bindungen und Mocking zwingend zu beachten.\n</li></ul>"}, {"id": "FIG-2a2c5c4f0c921fce", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm für synchrone BSW-API-Kaskade).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Aktivierung des Hardware-Sendezeitstempel-Mechanismus (Egress Timestamping) für einen dedizierten Ethernet-Sendepuffer gemäß IEEE 802.1AS (gPTP).\n</li><li><strong>Architektur-Einordnung:</strong> BSW-Kommunikationsstack der AUTOSAR Classic Platform. Das Modul <code>EthTSyn</code> (Time Synchronization over Ethernet) agiert als Client des <code>EthIf</code> (Ethernet Interface), welches die Anforderung an den MCAL-Treiber <code>Eth</code> (Ethernet Driver) durchreicht.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte BSW-Module (Lebenslinien):</strong>\n<ul class=\"fig-list\"><li><code>EthTSyn</code>: Obere Transportschicht für Zeitsynchronisation; initiiert die Zeitstempelerfassung für Sync-/Pdelay-Frames.\n</li><li><code>EthIf</code>: Hardware-Abstraktionsschicht; entkoppelt Controller-Indizes und leitet Anforderungen an den zuständigen Treiber weiter.\n</li><li><code>Eth</code>: MCAL-Treiber; führt hardwarenahe Zeitstempel-Operationen aus.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>EthIf_EnableEgressTimeStamp()</code>\n</li><li><code>Eth_ConvertTimeStamp()</code>\n</li></ul>\n</li><li><strong>Parameter &amp; Typen:</strong>\n<ul class=\"fig-list\"><li>Die Aufrufe sind ohne Parameterliste und ohne Rückgabewert spezifiziert.\n</li></ul>\n</li><li><strong>Guard Condition:</strong>\n<ul class=\"fig-list\"><li><code>[EthTSynHardwareTimestampSupport == TRUE]</code>: Pre-Compile- bzw. Link-Time-Schalter; kapselt den Aufruf gegen rein softwarebasierte Zeitstempel-Implementierungen ab.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> <code>EthTSyn</code> bereitet das Senden einer zeitsynchronisationskritischen PDU vor, nachdem zuvor über <code>EthIf_ProvideTxBuffer()</code> ein Sendepuffer allokiert wurde.\n</li><li><strong>Bedingungsprüfung:</strong> Lokale Evaluation des Konfigurationsparameters <code>EthTSynHardwareTimestampSupport</code>. Ist dieser <code>FALSE</code>, wird die Sequenz übersprungen (Software-Timestamping oder inkompatible Hardware).\n</li><li><strong>Synchrone Weiterleitung:</strong>\n<ul class=\"fig-list\"><li><code>EthTSyn</code> ruft blockierend <code>EthIf_EnableEgressTimeStamp()</code> auf.\n</li><li><code>EthIf</code> ruft synchron <code>Eth_ConvertTimeStamp()</code> am MCAL-Treiber <code>Eth</code> auf.\n</li></ul>\n</li><li><strong>Hardware-Parametrierung &amp; Rückmeldung:</strong>\n<ul class=\"fig-list\"><li>Der <code>Eth</code>-Treiber führt die Zeitstempeloperation aus.\n</li><li>Synchrone Rückmeldung kaskadierend über <code>EthIf</code> zurück an <code>EthTSyn</code>.\n</li></ul>\n</li><li><strong>Folgeschritt:</strong> Nach erfolgreicher Rückgabe stößt <code>EthTSyn</code> den eigentlichen Sendevorgang via <code>EthIf_Transmit()</code> an.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Timing &amp; Aufruf-Reihenfolge:</strong> Der Aufruf muss zwingend <strong>vor</strong> <code>EthIf_Transmit()</code> und <strong>nach</strong> erfolgreichem <code>EthIf_ProvideTxBuffer()</code> erfolgen. Eine Aktivierung nach Übergabe an die Hardware-Sendewarteschlange führt zum Verlust des Hardware-Zeitstempels.\n</li><li><strong>Konfigurationsabhängigkeit:</strong> \n<ul class=\"fig-list\"><li>Erfordert gesetztes <code>EthTSynHardwareTimestampSupport = TRUE</code>.\n</li><li>Sowohl <code>EthIf</code> als auch <code>Eth</code> müssen das Feature unterstützen (<code>EthEnableEgressTimeStamp == TRUE</code> bzw. äquivalente MCAL-Konfiguration).\n</li></ul>\n</li><li><strong>MCAL-Treiberanforderungen:</strong> Der Ethernet-Treiber muss sicherstellen, dass nach dem Senden der Frame-spezifische Egress-Timestamp erfasst und für den anschließenden Abruf via <code>Eth_GetEgressTimeStamp()</code> / <code>EthIf_GetEgressTimeStamp()</code> im Speicher vorgehalten wird.\n</li><li><strong>API-Signatur-Diskrepanz (Naming):</strong> In der AUTOSAR-SWS weicht die Binnen-Großschreibung zwischen den Layern minimal ab (<code>EthIf_EnableEgressTimeStamp</code> mit großem <code>S</code> vs. <code>Eth_EnableEgressTimestamp</code> mit kleinem <code>s</code>). Dies ist bei statischen Bindungen und Mocking zwingend zu beachten.\n</li></ul>"}, {"id": "FIG-455f4179b35b7f6e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm für synchrone BSW-API-Kaskade).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Aktivierung des Hardware-Sendezeitstempel-Mechanismus (Egress Timestamping) für einen dedizierten Ethernet-Sendepuffer gemäß IEEE 802.1AS (gPTP).\n</li><li><strong>Architektur-Einordnung:</strong> BSW-Kommunikationsstack der AUTOSAR Classic Platform. Das Modul <code>EthTSyn</code> (Time Synchronization over Ethernet) agiert als Client des <code>EthIf</code> (Ethernet Interface), welches die Anforderung an den MCAL-Treiber <code>Eth</code> (Ethernet Driver) durchreicht.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte BSW-Module (Lebenslinien):</strong>\n<ul class=\"fig-list\"><li><code>EthTSyn</code>: Obere Transportschicht für Zeitsynchronisation; initiiert die Zeitstempelerfassung für Sync-/Pdelay-Frames.\n</li><li><code>EthIf</code>: Hardware-Abstraktionsschicht; entkoppelt Controller-Indizes und leitet Anforderungen an den zuständigen Treiber weiter.\n</li><li><code>Eth</code>: MCAL-Treiber; führt hardwarenahe Zeitstempel-Operationen aus.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>EthIf_EnableEgressTimeStamp()</code>\n</li><li><code>Eth_ConvertTimeStamp()</code>\n</li></ul>\n</li><li><strong>Parameter &amp; Typen:</strong>\n<ul class=\"fig-list\"><li>Die Aufrufe sind ohne Parameterliste und ohne Rückgabewert spezifiziert.\n</li></ul>\n</li><li><strong>Guard Condition:</strong>\n<ul class=\"fig-list\"><li><code>[EthTSynHardwareTimestampSupport == TRUE]</code>: Pre-Compile- bzw. Link-Time-Schalter; kapselt den Aufruf gegen rein softwarebasierte Zeitstempel-Implementierungen ab.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> <code>EthTSyn</code> bereitet das Senden einer zeitsynchronisationskritischen PDU vor, nachdem zuvor über <code>EthIf_ProvideTxBuffer()</code> ein Sendepuffer allokiert wurde.\n</li><li><strong>Bedingungsprüfung:</strong> Lokale Evaluation des Konfigurationsparameters <code>EthTSynHardwareTimestampSupport</code>. Ist dieser <code>FALSE</code>, wird die Sequenz übersprungen (Software-Timestamping oder inkompatible Hardware).\n</li><li><strong>Synchrone Weiterleitung:</strong>\n<ul class=\"fig-list\"><li><code>EthTSyn</code> ruft blockierend <code>EthIf_EnableEgressTimeStamp()</code> auf.\n</li><li><code>EthIf</code> ruft synchron <code>Eth_ConvertTimeStamp()</code> am MCAL-Treiber <code>Eth</code> auf.\n</li></ul>\n</li><li><strong>Hardware-Parametrierung &amp; Rückmeldung:</strong>\n<ul class=\"fig-list\"><li>Der <code>Eth</code>-Treiber führt die Zeitstempeloperation aus.\n</li><li>Synchrone Rückmeldung kaskadierend über <code>EthIf</code> zurück an <code>EthTSyn</code>.\n</li></ul>\n</li><li><strong>Folgeschritt:</strong> Nach erfolgreicher Rückgabe stößt <code>EthTSyn</code> den eigentlichen Sendevorgang via <code>EthIf_Transmit()</code> an.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Timing &amp; Aufruf-Reihenfolge:</strong> Der Aufruf muss zwingend <strong>vor</strong> <code>EthIf_Transmit()</code> und <strong>nach</strong> erfolgreichem <code>EthIf_ProvideTxBuffer()</code> erfolgen. Eine Aktivierung nach Übergabe an die Hardware-Sendewarteschlange führt zum Verlust des Hardware-Zeitstempels.\n</li><li><strong>Konfigurationsabhängigkeit:</strong> \n<ul class=\"fig-list\"><li>Erfordert gesetztes <code>EthTSynHardwareTimestampSupport = TRUE</code>.\n</li><li>Sowohl <code>EthIf</code> als auch <code>Eth</code> müssen das Feature unterstützen (<code>EthEnableEgressTimeStamp == TRUE</code> bzw. äquivalente MCAL-Konfiguration).\n</li></ul>\n</li><li><strong>MCAL-Treiberanforderungen:</strong> Der Ethernet-Treiber muss sicherstellen, dass nach dem Senden der Frame-spezifische Egress-Timestamp erfasst und für den anschließenden Abruf via <code>Eth_GetEgressTimeStamp()</code> / <code>EthIf_GetEgressTimeStamp()</code> im Speicher vorgehalten wird.\n</li><li><strong>API-Signatur-Diskrepanz (Naming):</strong> In der AUTOSAR-SWS weicht die Binnen-Großschreibung zwischen den Layern minimal ab (<code>EthIf_EnableEgressTimeStamp</code> mit großem <code>S</code> vs. <code>Eth_EnableEgressTimestamp</code> mit kleinem <code>s</code>). Dies ist bei statischen Bindungen und Mocking zwingend zu beachten.\n</li></ul>"}], "trans": [{"from": "FIG-83517aaaf6e5b2fc", "to": "FIG-605bad33f004ce66", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-605bad33f004ce66", "to": "FIG-2a2c5c4f0c921fce", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Schnittstelle <code>EthIf_EnableEgressTimeStamp</code>: Parameterliste <code>(CtrlIdx: uint8, BufIdx: Eth_BufIdxType)</code> und Rückgabetyp <code>Std_ReturnType</code> wurden entfernt (<code>EthIf_EnableEgressTimeStamp()</code>).\n</li><li>Aufruf von <code>EthIf</code> an <code>Eth</code>: Ersetzt von <code>Eth_EnableEgressTimestamp(CtrlIdx: uint8, BufIdx: Eth_BufIdxType): Std_ReturnType</code> durch <code>Eth_ConvertTimeStamp()</code>.\n</li></ul>"}, {"from": "FIG-2a2c5c4f0c921fce", "to": "FIG-455f4179b35b7f6e", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
